previewCss:
.darma-loader-darma-b14-card-fan-spread { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #1e293b); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .82); position: relative; }
.darma-loader-darma-b14-card-fan-spread span { position: absolute; bottom: 5%; left: 34%; width: 32%; height: 66%; border-radius: 5px; transform-origin: bottom center; background: linear-gradient(158deg, #f8fafc, #e2e8f0); box-shadow: inset 0 0 0 2px var(--accent-2), 0 2px 6px rgba(15, 23, 42, .22); animation: darma-loader-darma-b14-card-fan-spread-fan calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.4, 0, .3, 1) infinite; }
.darma-loader-darma-b14-card-fan-spread span::after { content: ''; position: absolute; top: 16%; left: 30%; width: 40%; height: 26%; background: var(--accent); clip-path: polygon(50% 0, 100% 38%, 50% 100%, 0 38%); }
.darma-loader-darma-b14-card-fan-spread span:nth-child(1) { --a: -36deg; }
.darma-loader-darma-b14-card-fan-spread span:nth-child(2) { --a: -18deg; animation-delay: calc(var(--loader-speed, 1s) * .07); }
.darma-loader-darma-b14-card-fan-spread span:nth-child(3) { --a: 0deg; animation-delay: calc(var(--loader-speed, 1s) * .14); }
.darma-loader-darma-b14-card-fan-spread span:nth-child(4) { --a: 18deg; animation-delay: calc(var(--loader-speed, 1s) * .21); }
.darma-loader-darma-b14-card-fan-spread span:nth-child(5) { --a: 36deg; animation-delay: calc(var(--loader-speed, 1s) * .28); }
@keyframes darma-loader-darma-b14-card-fan-spread-fan { 0%, 12% { transform: rotate(0deg); } 44%, 70% { transform: rotate(var(--a)); } 92%, 100% { transform: rotate(0deg); } }

